import re

def to_underscore(s):
    if not isinstance(s, str):
        return str(s)

    if len(s) == 0:
        return s

    result = []
    i = 0
    n = len(s)

    while i < n:
        char = s[i]

        if char.isupper():
            if i > 0 and (s[i-1].islower() or s[i-1].isdigit()):
                result.append('_')
            result.append(char.lower())
        elif char.isdigit():
            if i > 0 and s[i-1].isalpha():
                result.append('_')
            result.append(char)
        else:
            result.append(char)

        i += 1

    return ''.join(result)
